  "Cada reporte contiene el mensaje señalado y hasta cinco mensajes anteriores. Los adjuntos se guardan en un bucket privado de evidencias.": {
    "en": "Each report includes the flagged message and up to five previous messages. Attachments are stored in a private evidence bucket.",
    "sl": "Vsako poročilo vsebuje označeno sporočilo in do pet predhodnih sporočil. Priloge so shranjene v zasebnem vsebniku dokazov.",
    "it": "Ogni segnalazione include il messaggio indicato e fino a cinque messaggi precedenti. Gli allegati vengono salvati in un bucket privato delle prove.",
    "fr": "Chaque signalement contient le message signalé et jusqu'à cinq messages précédents. Les pièces jointes sont stockées dans un espace privé de preuves.",
    "ja": "各通報には対象メッセージとその前の最大5件のメッセージが含まれます。添付ファイルは非公開の証拠保管領域に保存されます。",
    "zh-CN": "每份举报包含被举报消息及最多五条此前的消息。附件会保存在私有证据存储桶中。",
    "de": "Jeder Bericht enthält die gemeldete Nachricht und bis zu fünf vorherige Nachrichten. Anhänge werden in einem privaten Beweis-Speicher abgelegt.",
    "pt-PT": "Cada denúncia inclui a mensagem assinalada e até cinco mensagens anteriores. Os anexos são guardados num contentor privado de provas.",
    "gn": "Peteĩ marandu vai rehegua oguereko marandu ojehechaukáva ha cinco marandu mboyvegua peve. Oñembojoapy kuatiañe’ẽ oñeñongatu peteĩ ryru ñemiguápe.",
    "ca": "Cada informe inclou el missatge assenyalat i fins a cinc missatges anteriors. Els fitxers adjunts es guarden en un dipòsit privat de proves.",
    "gl": "Cada denuncia inclúe a mensaxe sinalada e ata cinco mensaxes anteriores. Os anexos gárdanse nun contedor privado de probas.",
    "eu": "Txosten bakoitzak salatutako mezua eta aurreko bost mezu gehienez biltzen ditu. Eranskinak froga-biltegi pribatu batean gordetzen dira.",
    "la": "Quaeque relatio nuntium notatum et usque ad quinque nuntios antecedentes continet. Adiuncta in receptaculo privato probationum servantur.",
    "es-jv": "Cada reporte contiene el mensaje señalado y hasta cinco mensajes anteriores. Los adjuntos se guardan en un almacén privado de evidencias."
  },
