  "Selecciona un canal en la barra lateral para conversar. Los canales de voz, anuncios y multimedia tienen su propio tipo y sus capacidades se irán habilitando por módulos.": {
    "en": "Select a channel in the sidebar to chat. Voice, announcement and media channels have their own types, and their features will be enabled module by module.",
    "sl": "Za pogovor izberi kanal v stranski vrstici. Glasovni, obvestilni in večpredstavnostni kanali imajo svoje vrste, njihove funkcije pa bodo omogočene postopoma po modulih.",
    "it": "Seleziona un canale nella barra laterale per chattare. I canali vocali, annunci e multimediali hanno un tipo specifico e le relative funzioni verranno abilitate modulo per modulo.",
    "fr": "Sélectionnez un salon dans la barre latérale pour discuter. Les salons vocaux, d'annonces et multimédias ont leur propre type et leurs fonctionnalités seront activées progressivement par module.",
    "ja": "会話するにはサイドバーでチャンネルを選択してください。音声、お知らせ、メディアチャンネルにはそれぞれ種類があり、機能はモジュールごとに順次有効になります。",
    "zh-CN": "在侧边栏中选择一个频道以开始聊天。语音、公告和媒体频道各有类型，其功能将按模块逐步启用。",
    "de": "Wähle in der Seitenleiste einen Kanal aus, um zu chatten. Sprach-, Ankündigungs- und Medienkanäle haben eigene Typen; ihre Funktionen werden schrittweise je Modul freigeschaltet.",
    "pt-PT": "Seleciona um canal na barra lateral para conversar. Os canais de voz, avisos e multimédia têm tipos próprios e as respetivas capacidades serão ativadas módulo a módulo.",
    "gn": "Eiporavo peteĩ canal barra lateral-pe eñemongeta hag̃ua. Canal ñe’ẽasãi, marandu ha multimedia oguereko tipo iñambuéva, ha umi mba’apo oñemyendyta módulo rupive.",
    "ca": "Selecciona un canal a la barra lateral per conversar. Els canals de veu, anuncis i multimèdia tenen tipus propis i les funcions s'aniran activant per mòduls.",
    "gl": "Selecciona unha canle na barra lateral para conversar. As canles de voz, avisos e multimedia teñen o seu propio tipo e as funcións iranse activando por módulos.",
    "eu": "Hautatu kanal bat alboko barran txateatzeko. Ahots-, iragarki- eta multimedia-kanalek mota propioa dute, eta gaitasunak moduluka gaituko dira.",
    "la": "Canalem in laterali elige ut colloquaris. Canales vocales, nuntiorum et multimediatici propria genera habent, facultates autem per modulos paulatim accendentur.",
    "es-jv": "Selecciona un canal en la barra lateral para conversar. Los canales de voz, anuncios y multimedia tienen su propio tipo y sus funciones se irán habilitando por módulos."
  },
  "Personaliza los fondos y la legibilidad de Nexus. Los cambios se aplican a la interfaz, sin modificar el tema de los demás usuarios.": {
    "en": "Customise Nexus backgrounds and readability. Changes apply to your interface without changing other users' themes.",
    "sl": "Prilagodi ozadja in berljivost Nexusa. Spremembe veljajo za tvoj vmesnik in ne spreminjajo teme drugih uporabnikov.",
    "it": "Personalizza gli sfondi e la leggibilità di Nexus. Le modifiche si applicano alla tua interfaccia senza cambiare il tema degli altri utenti.",
    "fr": "Personnalisez les arrière-plans et la lisibilité de Nexus. Les changements s'appliquent à votre interface sans modifier le thème des autres utilisateurs.",
    "ja": "Nexusの背景と読みやすさをカスタマイズできます。変更は自分の画面にのみ適用され、ほかのユーザーのテーマは変わりません。",
    "zh-CN": "自定义 Nexus 的背景和可读性。更改仅应用于你的界面，不会更改其他用户的主题。",
    "de": "Passe Hintergründe und Lesbarkeit von Nexus an. Änderungen gelten nur für deine Oberfläche und ändern nicht das Design anderer Benutzer.",
    "pt-PT": "Personaliza os fundos e a legibilidade do Nexus. As alterações aplicam-se à tua interface, sem modificar o tema dos outros utilizadores.",
    "gn": "Emboava Nexus fondo ha jehecha porã. Ñemoambue ojeporu nde interfaz-pe añoite, ndoambuéi ambue puruhára tema.",
    "ca": "Personalitza els fons i la llegibilitat de Nexus. Els canvis s'apliquen a la teva interfície i no modifiquen el tema dels altres usuaris.",
    "gl": "Personaliza os fondos e a lexibilidade de Nexus. Os cambios aplícanse á túa interface, sen modificar o tema dos demais usuarios.",
    "eu": "Pertsonalizatu Nexusen atzeko planoak eta irakurgarritasuna. Aldaketak zure interfazean soilik aplikatzen dira, beste erabiltzaileen gaia aldatu gabe.",
    "la": "Fundos et perspicuitatem Nexus constitue. Mutationes in tua interfacie tantum valent, aliorum usorum themata non mutantes.",
    "es-jv": "Personaliza los fondos y la legibilidad de Nexus. Los cambios solo afectan a tu interfaz."
  },
