  "al editar un canal, activa «Recibir avisos importantes del megagrupo» para mostrar los avisos publicados por el equipo de Nexus.": {
    "en": "when editing a channel, enable “Receive important megagroup announcements” to display announcements published by the Nexus team.",
    "sl": "pri urejanju kanala omogoči »Prejemaj pomembne objave megaskupine«, da prikažeš objave ekipe Nexusa.",
    "it": "quando modifichi un canale, attiva «Ricevi avvisi importanti del megagruppo» per mostrare gli avvisi pubblicati dal team Nexus.",
    "fr": "lors de la modification d'un salon, activez « Recevoir les annonces importantes du mégagroupe » pour afficher les annonces publiées par l'équipe Nexus.",
    "ja": "チャンネルの編集時に「メガグループの重要なお知らせを受信」を有効にすると、Nexusチームのお知らせが表示されます。",
    "zh-CN": "编辑频道时，启用“接收大型群组重要公告”，即可显示 Nexus 团队发布的公告。",
    "de": "Aktiviere beim Bearbeiten eines Kanals „Wichtige Megagruppen-Mitteilungen empfangen“, um Mitteilungen des Nexus-Teams anzuzeigen.",
    "pt-PT": "ao editar um canal, ativa «Receber avisos importantes do megagrupo» para mostrar os avisos publicados pela equipa do Nexus.",
    "gn": "Canal emboava jave, emyendy «Emoñandu megagrupo marandu iñimportánteva» ehecha hag̃ua Nexus equipo marandu.",
    "ca": "en editar un canal, activa «Rebre avisos importants del megagrup» per mostrar els avisos publicats per l'equip de Nexus.",
    "gl": "ao editar unha canle, activa «Recibir avisos importantes do megagrupo» para mostrar os avisos publicados polo equipo de Nexus.",
    "eu": "kanal bat editatzean, gaitu «Jaso megataldeko ohar garrantzitsuak» Nexus taldeak argitaratutako oharrak erakusteko.",
    "la": "canalem emendans, «Nuntios magni momenti circuli magni accipe» accende ut nuntios gregis Nexus ostendas.",
    "es-jv": "al editar un canal, activa «Recibir avisos importantes del megagrupo» para mostrar los avisos publicados por el equipo de Nexus."
  },
  "Amplia colección de emojis estándar, emojis personalizados y stickers de tu cuenta, conversación o megagrupo. Los emojis también pueden usarse como reacciones.": {
    "en": "A wide collection of standard emojis, custom emojis and stickers from your account, conversation or megagroup. Emojis can also be used as reactions.",
    "sl": "Obsežna zbirka standardnih emojijev, emojijev po meri in nalepk iz tvojega računa, pogovora ali megaskupine. Emojije lahko uporabiš tudi kot odzive.",
    "it": "Ampia raccolta di emoji standard, emoji personalizzati e sticker del tuo account, della conversazione o del megagruppo. Gli emoji possono essere usati anche come reazioni.",
    "fr": "Large collection d'émojis standard, d'émojis personnalisés et de stickers provenant de votre compte, conversation ou mégagroupe. Les émojis peuvent également servir de réactions.",
    "ja": "アカウント、会話、メガグループの標準絵文字、カスタム絵文字、ステッカーを幅広く利用できます。絵文字はリアクションにも使用できます。",
    "zh-CN": "提供来自你的账户、对话或大型群组的标准表情符号、自定义表情符号和贴纸。表情符号也可用作回应。",
    "de": "Große Auswahl an Standard-Emojis, eigenen Emojis und Stickern aus deinem Konto, deiner Unterhaltung oder Megagruppe. Emojis können auch als Reaktionen verwendet werden.",
    "pt-PT": "Coleção alargada de emojis padrão, emojis personalizados e autocolantes da tua conta, conversa ou megagrupo. Os emojis também podem ser usados como reações.",
    "gn": "Oĩ hetaiterei emoji tee, emoji tee ha sticker nde cuenta, ñomongeta térã megagrupo-gui. Emoji ikatu ojeporu mbohovái ramo avei.",
    "ca": "Àmplia col·lecció d'emojis estàndard, emojis personalitzats i adhesius del teu compte, conversa o megagrup. Els emojis també es poden fer servir com a reaccions.",
    "gl": "Ampla colección de emojis estándar, emojis personalizados e adhesivos da túa conta, conversa ou megagrupo. Os emojis tamén poden empregarse como reaccións.",
    "eu": "Emoji estandarren, emoji pertsonalizatuen eta zure kontuko, elkarrizketako edo megataldeko eranskailuen bilduma zabala. Emojiak erreakzio gisa ere erabil daitezke.",
    "la": "Amplam collectionem imaginum emoji ordinariarum, propriarum et pittaculorum ex ratione tua, colloquio aut circulo magno. Imagines emoji etiam pro reactionibus adhiberi possunt.",
    "es-jv": "Amplia colección de emojis estándar, personalizados y stickers de tu cuenta, conversación o megagrupo. También puedes usarlos como reacciones."
  },
