  "¿Eliminar la identidad @{{username}}? Los mensajes anteriores dejarán de mostrar la marca ALT y usarán el perfil principal.": {
    "en": "Delete the @{{username}} identity? Previous messages will no longer show the ALT label and will use the main profile.",
    "sl": "Izbrišem identiteto @{{username}}? Prejšnja sporočila ne bodo več prikazovala oznake ALT in bodo uporabljala glavni profil.",
    "it": "Eliminare l'identità @{{username}}? I messaggi precedenti non mostreranno più l'etichetta ALT e useranno il profilo principale.",
    "fr": "Supprimer l'identité @{{username}} ? Les anciens messages n'afficheront plus la mention ALT et utiliseront le profil principal.",
    "ja": "@{{username}} のIDを削除しますか？過去のメッセージにはALTラベルが表示されなくなり、メインプロフィールが使用されます。",
    "zh-CN": "删除 @{{username}} 身份？此前的消息将不再显示 ALT 标记，并改用主个人资料。",
    "de": "Die Identität @{{username}} löschen? Frühere Nachrichten zeigen dann nicht mehr die ALT-Kennzeichnung und verwenden das Hauptprofil.",
    "pt-PT": "Eliminar a identidade @{{username}}? As mensagens anteriores deixarão de mostrar a marca ALT e passarão a usar o perfil principal.",
    "gn": "Embogue identidad @{{username}}? Marandu ymaguare ndohechaukamo’ãvéi ALT ha oiporúta perfil tenondegua.",
    "ca": "Eliminar la identitat @{{username}}? Els missatges anteriors deixaran de mostrar la marca ALT i faran servir el perfil principal.",
    "gl": "Eliminar a identidade @{{username}}? As mensaxes anteriores deixarán de mostrar a marca ALT e usarán o perfil principal.",
    "eu": "Ezabatu @{{username}} identitatea? Aurreko mezuek ez dute ALT marka erakutsiko eta profil nagusia erabiliko dute.",
    "la": "Identitatem @{{username}} delere? Epistulae priores notam ALT non iam ostendent et persona principali utentur.",
    "es-jv": "¿Eliminar la identidad @{{username}}? Los mensajes anteriores dejarán de mostrar la marca ALT y usarán el perfil principal."
  },
