    "ja": "メガグループの外観を調整できます。Nexusは許可されていないルールやプロパティを除外します。スクリプト、インポート、外部リンクを追加しないでください。",
    "zh-CN": "允许调整大型群组的视觉元素。Nexus 会过滤不允许的规则和属性；请勿添加脚本、导入语句或外部链接。",
    "de": "ermöglicht die Anpassung der Megagruppen-Optik. Nexus filtert unzulässige Regeln und Eigenschaften; füge keine Skripte, Imports oder externen Links hinzu.",
    "pt-PT": "permite ajustar os elementos visuais do megagrupo. O Nexus filtra regras e propriedades não permitidas; não adiciones scripts, imports nem ligações externas.",
    "gn": "omohenda megagrupo mba’e ojehecháva. Nexus oipe’a regla ha propiedad ndikatúiva; ani emoĩ script, import térã joajuha okápegua.",
    "ca": "permet ajustar els elements visuals del megagrup. Nexus filtra les regles i propietats no permeses; no afegeixis scripts, imports ni enllaços externs.",
    "gl": "permite axustar elementos visuais do megagrupo. Nexus filtra as regras e propiedades non permitidas; non engadas scripts, imports nin ligazóns externas.",
    "eu": "megataldearen ikusizko elementuak doitzeko aukera ematen du. Nexusek baimendu gabeko arauak eta propietateak iragazten ditu; ez gehitu scriptik, importaziorik edo kanpoko estekarik.",
    "la": "elementa visualia circuli magni mutare sinit. Nexus regulas proprietatesque non licitas colat; ne scripta, importationes aut nexus externos addas.",
    "es-jv": "permite ajustar elementos visuales del megagrupo. Nexus filtra reglas y propiedades no permitidas; no añadas scripts, imports ni enlaces externos."
